const input = $('Webhook — Recibir solicitud de contenido').first().json.body || {};
const products = $('GET /products — Catálogo Golden Harvest').all().map(i => i.json);
const platform = input.platform || 'instagram';
const tone = input.tone || 'formal';
const product = input.product_sku
  ? products.find(p => p.sku === input.product_sku) || products[0]
  : products[Math.floor(Math.random() * products.length)];
const templates = {
  instagram: {
    formal: `✨ Descubrí la calidad artesanal de Golden Harvest.\n\n🫒 ${product.nombre}\nElaborado con los mejores ingredientes de la región.\n\n#GoldenHarvest #ProductosArtesanales #Gourmet`,
    casual: `¿Ya probaste nuestro ${product.nombre.split(' ').slice(0,3).join(' ')}? 😍\n\nUn clásico que no podés perderte.\n\n#GoldenHarvest #FoodLovers`
  },
  whatsapp: {
    formal: `Hola! Le compartimos nuestra última novedad:\n\n*${product.nombre}*\nPrecio: $${product.precio_unitario.toLocaleString('es-AR')} por unidad\n\n¿Le interesa hacer un pedido? Contáctenos.`,
    casual: `¡Hola! 👋 No te pierdas nuestro *${product.nombre}*\n💰 $${product.precio_unitario.toLocaleString('es-AR')} la unidad\n\n¿Hacemos un pedido? 🛒`
  }
};
const caption = templates[platform]?.[tone] || templates.instagram.formal;
const imagePrompt = `product photo of ${product.nombre}, artisanal food, golden harvest argentina, white background, professional`;
return [{ json: { product, platform, tone, caption, image_prompt: imagePrompt, image_url: `https://image.pollinations.ai/prompt/${encodeURIComponent(imagePrompt)}?width=1080&height=1080&nologo=true` } }];

