=Generá contenido de redes sociales para Golden Harvest S.A. sobre el siguiente tema: {{ $json.Topic }}

Palabras clave / hashtags: {{ $json['Keywords or Hashtags (optional)'] || 'GoldenHarvest, ProductosGourmet' }}

Devolvé un JSON con el siguiente formato exacto (sin texto adicional antes o después):
{
  "instagram": "<caption para Instagram con emojis y hashtags>",
  "facebook": "<post para Facebook, tono profesional>",
  "twitter": "<tweet de máximo 280 caracteres>",
  "linkedin": "<artículo profesional para LinkedIn>",
  "tiktok": "<guión corto para TikTok video>",
  "threads": "<post para Threads>",
  "youtube_shorts": "<descripción para YouTube Shorts>"
}

parameters.jsCode:
// Thesis-mode content generator for Golden Harvest S.A.
// Replaces Ollama LLM for demo purposes - generates realistic content via templates
const formData = $input.first().json;
const topic = formData['Topic'] || formData['topic'] || 'Productos Golden Harvest';
const keywords = formData['Keywords or Hashtags (optional)'] || formData['keywords'] || 'GoldenHarvest, ProductosGourmet';

// Extract hashtags from keywords
const hashtagList = keywords.split(',').map(k => {
  const cleaned = k.trim().replace(/^#/, '').replace(/\s+/g, '');
  return `#${cleaned}`;
}).join(' ');

// Company context
const company = 'Golden Harvest S.A.';
const products = ['aceitunas artesanales', 'pesto casero', 'chutney gourmet', 'mermeladas artesanales', 'conservas premium'];
const product = products[Math.floor(Math.random() * products.length)];

// Generate platform-specific content
const instagram = `✨ ¡Novedad en Golden Harvest! 🇦🇷\n\n${topic}\n\nNuestros ${product} son elaborados con ingredientes seleccionados del campo argentino. Calidad artesanal que se nota en cada bocado.\n\nIdeal para supermercados, distribuidores y restaurantes gourmet que buscan lo mejor.\n\n🫒 Consultá disponibilidad y precios mayoristas\n📩 ventas@goldenharvest.com.ar\n\n${hashtagList} #Argentina #Artesanal #FoodIndustry`;

const facebook = `${company} | ${topic}\n\nEstamos emocionados de compartir las últimas novedades de nuestra línea de ${product}. Elaborados con la tradición artesanal argentina y los más altos estándares de calidad.\n\nNuestros productos están disponibles para distribuidores mayoristas, cadenas de supermercados y restaurantes que valoran la diferencia de lo artesanal.\n\n¿Querés ser distribuidor oficial? Contactanos y te enviamos nuestro catálogo completo.\n\n${hashtagList}`;

const twitter = `🌿 ${company}: ${topic}. ${product} de calidad artesanal argentina para el mercado B2B. Supermercados, distribuidores y restaurantes: consultá nuestro catálogo. ${hashtagList}`.substring(0, 280);

const linkedin = `En ${company} continuamos innovando con ${topic}.\n\nNuestra línea de ${product} representa el compromiso con la calidad artesanal argentina que nos distingue en el mercado de alimentos premium.\n\n📊 Datos del mercado: el segmento de conservas artesanales en Argentina creció 23% interanual, impulsado por la demanda de productos premium en canales modernos.\n\nBuscamos ampliar nuestra red de distribuidores en todo el país. Si tu empresa comparte nuestra visión de calidad, te invitamos a conocer nuestra propuesta comercial.\n\n#FoodIndustry #Argentina #B2BFood #DistribuciónMayorista ${hashtagList}`;

const tiktok = `[GUIÓN TIKTOK — 30 segundos]\n\n0-3s: Toma de los productos Golden Harvest en mesa rústica de madera\n3-10s: Manos abriendo un frasco de ${product} — sonido del sello al abrirse\n10-20s: Close-up de textura y color — voz en off: "${topic}"\n20-27s: Plato gourmet con el producto — branding Golden Harvest\n27-30s: Logo + tagline: "Calidad artesanal argentina"\n\nMúsica: folk argentino instrumental\nHashtags: ${hashtagList} #FoodTok #Gourmet`;

const threads = `${topic} 🫒\n\nEn @GoldenHarvestAR estamos redefiniendo lo que significa la calidad artesanal en ${product}.\n\nPara los que buscan diferenciarse con productos premium en sus góndolas o menús.\n\n${hashtagList}`;

const youtube_shorts = `[TÍTULO] ${topic} — ${company}\n[DESCRIPCIÓN] Descubrí la nueva propuesta de Golden Harvest S.A.: ${product} elaborados con la mejor tradición artesanal argentina. Ideal para distribuidores, supermercados y restaurantes gourmet. Contactanos para nuestro catálogo B2B.\n\n${hashtagList} #Shorts #GoldenHarvest #FoodArgentina\n\n[DURACIÓN SUGERIDA] 45-60 segundos\n[LLAMADA A ACCIÓN] Link al catálogo en bio`;

return [{
  json: {
    topic,
    keywords,
    company,
    generatedBy: 'Golden Harvest Content Engine (Thesis Demo)',
    timestamp: new Date().toISOString(),
    platforms: {
      instagram,
      facebook,
      twitter,
      linkedin,
      tiktok,
      threads,
      youtube_shorts
    }
  }
}];

// NOTE: n8n task runner disallows 'fs' module — file writing done via HTTP request in production
// For thesis demo: log summary and return structured data
const data = $input.first().json;
const platforms = data.platforms || {};

const output = {
  timestamp: data.timestamp || new Date().toISOString(),
  workflow: 'WF4 — Social Media Content Engine',
  company: 'Golden Harvest S.A.',
  mode: 'TESIS — Content Engine (sin credenciales externas)',
  topic: data.topic,
  keywords: data.keywords,
  platforms
};

// Console summary (visible in n8n execution logs)
const platformNames = Object.keys(platforms);
console.log('=== Golden Harvest Social Media Content Generated ===');
console.log('Topic:', data.topic);
console.log('Platforms generated:', platformNames.join(', '));
platformNames.forEach(p => {
  const text = (platforms[p] || '').substring(0, 100);
  console.log(`[${p.toUpperCase()}] ${text}...`);
});
console.log('Output (full JSON):');
console.log(JSON.stringify(output, null, 2));

return [{ json: {
  success: true,
  outputData: output,
  topic: data.topic,
  platformsGenerated: platformNames,
  previewInstagram: (platforms.instagram || '').substring(0, 300),
  previewLinkedIn: (platforms.linkedin || '').substring(0, 300),
  previewTwitter: (platforms.twitter || '').substring(0, 280),
  previewFacebook: (platforms.facebook || '').substring(0, 300)
} }];
